# Generated by packaging/homebrew/update-formula.sh from a SHA256SUMS whose Ed25519 signature was verified.
# Install: brew install omegacomputes/tap/pewter
class Pewter < Formula
  desc "Orchestration for GPU compute, from the terminal (alias: pew)"
  homepage "https://omegacompute.com"
  version "0.1.0"
  license "Apache-2.0"

  base = "https://omegacompute.com/cli/pewter-v#{version}"

  on_macos do
    on_arm do
      url "#{base}-darwin-arm64.tar.gz"
      sha256 "2b173f5b6f14f524f1d1a14798a44a012209500b9b12c6877c0daaf9cb332f29"
    end
    on_intel do
      url "#{base}-darwin-amd64.tar.gz"
      sha256 "d732883968f623c570425b2f78ce8265751bdc66385d2f7c60577bcf015bff8e"
    end
  end

  on_linux do
    on_arm do
      url "#{base}-linux-arm64.tar.gz"
      sha256 "d62fe41428be60f40cb5031ff5a93c7a804f372a064030930d57126da888dc44"
    end
    on_intel do
      url "#{base}-linux-amd64.tar.gz"
      sha256 "8350e02a4e29885610f95e9e2ce39c896dd3c7115e3a93b851933e23ea4d146b"
    end
  end

  def install
    bin.install "pewter"
    doc.install "LICENSE", "NOTICE"
    bin.install_symlink "pewter" => "pew"
    generate_completions_from_executable(bin/"pewter", "completion", shells: [:bash, :zsh])
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/pewter version")
    assert_equal shell_output("#{bin}/pewter version"), shell_output("#{bin}/pew version")
  end
end
